import{_ as t}from"./chunks/thumb-06.CdSJlpm1.js";import{_ as a,H as r,f as o,i as s}from"./chunks/framework.Cvt1eIE0.js";const h=JSON.parse('{"title":"「慢就业」上热搜：不是懒，是选项变贵了","description":"","frontmatter":{"title":"「慢就业」上热搜：不是懒，是选项变贵了","date":"2026-03-22T00:00:00.000Z","category":"阅读","tags":["阅读","评论","社会"],"excerpt":"考公热、Gap 年、全职儿女——标签背后是同一件事：年轻人对确定性出价的重新谈判。"},"headers":[],"relativePath":"posts/阅读/gen-z-employment-discourse-2026.md","filePath":"posts/阅读/gen-z-employment-discourse-2026.md"}'),n={name:"posts/阅读/gen-z-employment-discourse-2026.md"};function i(l,e,p,c,d,m){return r(),o("div",null,[...e[0]||(e[0]=[s('<img src="'+t+'" alt="配图" class="article-banner" loading="lazy"><h1 id="「慢就业」上热搜" tabindex="-1">「慢就业」上热搜 <a class="header-anchor" href="#「慢就业」上热搜" aria-label="Permalink to &quot;「慢就业」上热搜&quot;">​</a></h1><p>媒体喜欢二元标题：要么「躺平」，要么「奋斗」。真实数据区间里，更多人处在<strong>试探、备考、转行、兼职、照顾家庭</strong>的叠加态。热搜抓的是极端样本，讨论却常常泛化到整代人。</p><h2 id="三个被混在一起的变量" tabindex="-1">三个被混在一起的变量 <a class="header-anchor" href="#三个被混在一起的变量" aria-label="Permalink to &quot;三个被混在一起的变量&quot;">​</a></h2><p><strong>宏观岗位结构</strong>：部分行业缩编与 AI 辅助并行，入门岗位门槛形态在变。<br><strong>生活成本</strong>：房租、教育、医疗预期，影响「先就业还是先稳住」的排序。<br><strong>社会比较</strong>：同辈在社交平台展示的轨迹，会放大焦虑，却不等于统计事实。</p><h2 id="评论时少做道德审判" tabindex="-1">评论时少做道德审判 <a class="header-anchor" href="#评论时少做道德审判" aria-label="Permalink to &quot;评论时少做道德审判&quot;">​</a></h2><p>把 Gap 年说成浪费，把考公说成逃避，都太省事。更有用的问法是：</p><ul><li>家庭现金流能否承受 6–12 个月探索期？</li><li>探索期是否有<strong>可验证产出</strong>（作品、证书、项目）？</li><li>政策与培训资源是否对准<strong>真实缺口行业</strong>？</li></ul><h2 id="收束" tabindex="-1">收束 <a class="header-anchor" href="#收束" aria-label="Permalink to &quot;收束&quot;">​</a></h2><p>热搜需要对立面才能传播；个人路径却往往<strong>不对立</strong>。把讨论从「对不对」改成「成本谁付、信息是否对称」，争论会少很多，理解会多一点。</p><hr><p><em>非劳动经济学论文，只是一则评论笔记。</em></p>',12)])])}const u=a(n,[["render",i]]);export{h as __pageData,u as default};
